// @story:SCRUM-27
// @ac:2
// @design:D17
// @type:functional
// @technique:equivalence-partitioning
test("AC-2 Tracking an order shows its status and ordered products", async ({ page }) => {
  await test.step("Given I am logged in as a registered customer", async () => {
    await page.goto("/#/login");
    const dismissBtn = page.getByRole("button", { name: "dismiss cookie message" });
    if (await dismissBtn.isVisible()) {
      await dismissBtn.click();
    }
    const welcomeClose = page.getByRole("button", { name: "Close Welcome Banner" });
    if (await welcomeClose.isVisible()) {
      await welcomeClose.click();
    }
    await page.getByLabel("Email").fill(process.env["AQA_APP_USER"] ?? "");
    await page.getByRole("textbox", { name: "Text field for the login password" }).fill(process.env["AQA_APP_PASS"] ?? "");
    await page.getByRole("button", { name: "Login" }).click();
    const loginResponse = await page.waitForResponse(r => r.url().includes("/rest/user/login") && r.request().method() === "POST");
    expect(loginResponse.status(), "Login must succeed (precondition: registered account with orders)").toBe(200);
    await expect(page.getByRole("button", { name: "Show/hide account menu" })).toBeVisible({ timeout: 10000 });
  });

  await test.step("When I navigate to \"/#/order-history\"", async () => {
    await page.goto("/#/order-history");
  });

  await test.step("And I click the track order button for the first order", async () => {
    // The registered customer has orders; click the first track button
    const trackBtn = page.locator("mat-icon").filter({ hasText: "track_changes" }).first();
    await expect(trackBtn).toBeVisible({ timeout: 10000 });
    await trackBtn.click();
  });

  await test.step("Then the page displays \"Ordered products\"", async () => {
    await expect(page.getByRole("heading", { name: "Ordered products" })).toBeVisible();
  });

  await test.step("And the order status section is visible", async () => {
    await expect(page.getByRole("heading", { name: "Expected Delivery" })).toBeVisible();
  });
});

// @story:SCRUM-27
// @ac:3
// @design:D18
// @type:functional
// @technique:equivalence-partitioning
test("AC-3a Order history only shows the current customer's own orders", async ({ page }) => {
  await test.step("Given I am logged in as a registered customer", async () => {
    await page.goto("/#/login");
    const dismissBtn = page.getByRole("button", { name: "dismiss cookie message" });
    if (await dismissBtn.isVisible()) {
      await dismissBtn.click();
    }
    const welcomeClose = page.getByRole("button", { name: "Close Welcome Banner" });
    if (await welcomeClose.isVisible()) {
      await welcomeClose.click();
    }
    await page.getByLabel("Email").fill(process.env["AQA_APP_USER"] ?? "");
    await page.getByLabel("Password").fill(process.env["AQA_APP_PASS"] ?? "");
    await page.getByRole("button", { name: "Login" }).click();
    await expect(page.getByRole("button", { name: "Show/hide account menu" })).toBeVisible({ timeout: 10000 });
  });

  await test.step("When I navigate to \"/#/order-history\"", async () => {
    await page.goto("/#/order-history");
  });

  await test.step("Then I only see orders belonging to the current user", async () => {
    // Verify the order history page loaded for the current user by checking the API response
    const response = await page.request.get("/api/Orders?userId=me");
    expect(response.status(), "Order history API should return 200 for the current user").toBe(200);
    const body = await response.json();
    // Every order in the response must belong to the same user (no cross-user leakage on this endpoint)
    const orders = body.data ?? body;
    if (Array.isArray(orders) && orders.length > 0) {
      const userIds = [...new Set(orders.map((o: any) => o.UserId))];
      expect(userIds.length, "Order history should only contain orders from one user").toBe(1);
    }
  });
});

