test("AC-3b Tracking an order by number does not reveal another customer's order to a different signed-in user", async ({ page }) => {
  await test.step("Given I am logged in as a registered customer", async () => {
    await page.goto("/#/login");
    const dismissBtn = page.getByRole("button", { name: "dismiss cookie message" });
    if (await dismissBtn.isVisible()) {
      await dismissBtn.click();
    }
    const welcomeClose = page.getByRole("button", { name: "Close Welcome Banner" });
    if (await welcomeClose.isVisible()) {
      await welcomeClose.click();
    }
    await page.getByLabel("Email").fill(process.env["AQA_APP_USER"] ?? "");
    await page.getByLabel("Password").fill(process.env["AQA_APP_PASS"] ?? "");
    await page.getByRole("button", { name: "Login" }).click();
    await expect(page.getByRole("button", { name: "Show/hide account menu" })).toBeVisible({ timeout: 10000 });
  });

  await test.step("When I navigate to \"/#/track-result?orderId=1\"", async () => {
    // orderId=1 belongs to another customer (admin/Jim); this customer should not see its details
    await page.goto("/#/track-result?orderId=1");
  });

  await test.step("Then the page does not display another customer's order details", async () => {
    // The page should either show no results or redirect; it should NOT show "Ordered products" with real data
    // If track-result shows "undefined" order (as seen in snapshot: "Search Results - undefined"), the table should be empty
    const orderedProductsHeading = page.getByRole("heading", { name: "Ordered products" });
    const tableRows = page.locator("mat-table mat-row, table tbody tr");
    // Either the heading is absent OR the product table has no data rows
    const headingVisible = await orderedProductsHeading.isVisible();
    if (headingVisible) {
      // Heading is present but the table must have no product rows (no cross-user product data)
      await expect(tableRows).toHaveCount(0);
    }
    // If heading is not visible, the page correctly shows no order details — pass
  });
});

// @story:SCRUM-27
// @bug:SCRUM-28
// @design:D20
// @type:confirmation
// @technique:error-guessing
test("AC-3c Order tracking does not show another customer's order to an anonymous user", async ({ page }) => {
  test.fail(true, "Bug #SCRUM-28 Active: Order tracking shows any order to anyone who has its number, signed in or not");

  await test.step("Given I am on the login page", async () => {
    await page.goto("/#/login");
    const dismissBtn = page.getByRole("button", { name: "dismiss cookie message" });
    if (await dismissBtn.isVisible()) {
      await dismissBtn.click();
    }
  });

  await test.step("When I navigate to \"/#/track-result?orderId=1\"", async () => {
    await page.goto("/#/track-result?orderId=1");
  });

  await test.step("Then the page does not display order details for an anonymous user", async () => {
    // An anonymous (not logged-in) user should NOT be able to see order details by guessing an order ID
    // The page should redirect to login or show no order content
    await expect(page.getByRole("heading", { name: "Ordered products" })).not.toBeVisible();
  });
});

